import SwiftUI

struct ManageGoalsView: View {
    
    // Use the same DashboardViewModel
    // that the Dashboard is already using
    @ObservedObject var viewModel: DashboardViewModel
    
    
    // Weight goal input
    @State private var weightGoalType = "Lose Weight"
    @State private var weightAmount = ""
    
    
    // Step goal input
    @State private var stepTarget = ""
    
    // Weight goal timeframe
    @State private var hasWeightTargetDate = false
    @State private var weightTargetDate = Date()

    // Step goal timeframe
    @State private var hasStepTargetDate = false
    @State private var stepTargetDate = Date()

    
    
    // Local messages
    @State private var errorMessage = ""
    @State private var successMessage = ""
    
    
    // Prevent double-tapping while saving
    @State private var isSavingWeightGoal = false
    @State private var isSavingStepGoal = false
    
    
    let weightGoalOptions = [
        "Lose Weight",
        "Maintain Weight",
        "Gain Weight"
    ]
    
    
    var body: some View {
        
        Form {
            
            // ---------------------------------
            // Current Goals
            // ---------------------------------
            
            Section("Current Goals") {
                
                // Current Weight Goal
                if let weightGoal = viewModel.weightGoal {
                    
                    VStack(
                        alignment: .leading,
                        spacing: 6
                    ) {
                        
                        Text("Weight Goal")
                            .font(.caption)
                            .foregroundColor(.secondary)
                        
                        Text(
                            viewModel.formatGoalName(
                                for: weightGoal
                            )
                        )
                        .fontWeight(.semibold)
                        
                        Text(
                            "\(weightGoal.target_value.formatted()) \(weightGoal.unit)"
                        )
                        .foregroundColor(.secondary)
                        
                        if let targetDate = weightGoal.target_date {

                            Text("Complete by: \(formatGoalDate(targetDate))")
                                .font(.subheadline)
                                .foregroundColor(.secondary)
                            
                            // Show the time remaining
                            Text(goalTimeRemaining(targetDate))
                                    .font(.caption)
                                    .foregroundColor(.secondary)
                        }
                        
                        if weightGoal.goal_type != "maintain_weight" {

                            if let currentWeight = viewModel.currentWeight {

                                ProgressView(
                                    value: viewModel.goalProgress(for: weightGoal)
                                )

                                Text(
                                    "\(Int(viewModel.goalProgress(for: weightGoal) * 100))% complete"
                                )
                                .font(.caption)
                                .foregroundColor(.secondary)

                                Text("Current weight: \(currentWeight.formatted()) lbs")
                                    .font(.caption)
                                    .foregroundColor(.secondary)

                            } else {

                                Text("Update your weight to see progress.")
                                    .font(.caption)
                                    .foregroundColor(.secondary)
                            }
                        }
                    }
                    
                } else {
                    
                    Text("No active weight goal.")
                        .foregroundColor(.secondary)
                }
                
                
                // Current Step Goal
                if let stepGoal = viewModel.stepGoal {
                    
                    VStack(
                        alignment: .leading,
                        spacing: 6
                    ) {
                        
                        Text("Daily Step Goal")
                            .font(.caption)
                            .foregroundColor(.secondary)
                        
                        Text(
                            "\(stepGoal.target_value.formatted()) steps"
                        )
                        .fontWeight(.semibold)
                        
                        if let targetDate = stepGoal.target_date {

                                Text("Review on: \(formatGoalDate(targetDate))")
                                    .font(.subheadline)
                                    .foregroundColor(.secondary)
                            
                            // Show the time remaining
                            Text(goalTimeRemaining(targetDate))
                                    .font(.caption)
                                    .foregroundColor(.secondary)
                            }
                        
                        if let steps = viewModel.steps,
                           stepGoal.target_value > 0 {

                            ProgressView(
                                value: viewModel.goalProgress(for: stepGoal)
                            )

                            Text(
                                "\(Int(viewModel.goalProgress(for: stepGoal) * 100))% complete"
                            )
                            .font(.caption)
                            .foregroundColor(.secondary)

                            Text(
                                "\(steps.formatted()) / \(stepGoal.target_value.formatted()) steps"
                            )
                            .font(.caption)
                            .foregroundColor(.secondary)

                        } else {

                            Text("Load HealthKit steps to see progress.")
                                .font(.caption)
                                .foregroundColor(.secondary)
                        }
                    }
                    
                } else {
                    
                    Text("No active daily step goal.")
                        .foregroundColor(.secondary)
                }
            }
            
            
            // ---------------------------------
            // Weight Goal
            // ---------------------------------
            
            Section("Change Weight Goal") {
                
                Picker(
                    "Goal Type",
                    selection: $weightGoalType
                ) {
                    
                    ForEach(
                        weightGoalOptions,
                        id: \.self
                    ) { option in
                        
                        Text(option)
                    }
                }
                
                
                // Only ask for an amount
                // when losing or gaining weight
                if weightGoalType != "Maintain Weight" {
                    
                    HStack {
                        
                        Text(
                            weightGoalType == "Lose Weight"
                            ? "Target Loss:"
                            : "Target Gain:"
                        )
                        
                        TextField(
                            "e.g. 10",
                            text: $weightAmount
                        )
                        .keyboardType(.decimalPad)
                        .multilineTextAlignment(.trailing)
                        
                        Text("lbs")
                            .foregroundColor(.secondary)
                    }
                }
                
                
                Toggle(
                    "Set a target completion date",
                    isOn: $hasWeightTargetDate
                )

                if hasWeightTargetDate {

                    DatePicker(
                        "Complete By",
                        selection: $weightTargetDate,
                        in: Calendar.current.startOfDay(for: Date())...,
                        displayedComponents: .date
                    )
                }

                
                Button {
                    
                    saveWeightGoal()
                    
                } label: {
                    
                    if isSavingWeightGoal {
                        
                        ProgressView()
                        
                    } else {
                        
                        Text("Save Weight Goal")
                    }
                }
                .disabled(isSavingWeightGoal)
            }
            
            
            // ---------------------------------
            // Daily Step Goal
            // ---------------------------------
            
            Section("Daily Step Goal") {
                
                HStack {
                    
                    Text("Target:")
                    
                    TextField(
                        "e.g. 10000",
                        text: $stepTarget
                    )
                    .keyboardType(.numberPad)
                    .multilineTextAlignment(.trailing)
                    
                    Text("steps")
                        .foregroundColor(.secondary)
                }
                
                Toggle(
                    "Set a plan review date",
                    isOn: $hasStepTargetDate
                )

                if hasStepTargetDate {

                    DatePicker(
                        "Review On",
                        selection: $stepTargetDate,
                        in: Calendar.current.startOfDay(for: Date())...,
                        displayedComponents: .date
                    )
                }

                
                Button {
                    
                    saveStepGoal()
                    
                } label: {
                    
                    if isSavingStepGoal {
                        
                        ProgressView()
                        
                    } else {
                        
                        Text("Save Step Goal")
                    }
                }
                .disabled(isSavingStepGoal)
            }
            
            
            // ---------------------------------
            // Messages
            // ---------------------------------
            
            if !errorMessage.isEmpty {
                
                Section {
                    
                    Text(errorMessage)
                        .foregroundColor(.red)
                }
            }
            
            
            if !successMessage.isEmpty {
                
                Section {
                    
                    Text(successMessage)
                        .foregroundColor(.green)
                }
            }
            
            // MARK: - Goal History

            Section("Goal History") {

                NavigationLink {

                    GoalHistoryView()

                } label: {

                    Label(
                        "View Completed Goals",
                        systemImage: "clock.arrow.circlepath"
                    )
                }
            }
        }
        .navigationTitle("Manage Goals")
        .navigationBarTitleDisplayMode(.inline)
    }
    
    
    // MARK: - Save Weight Goal
    
    private func saveWeightGoal() {
        
        errorMessage = ""
        successMessage = ""
        
        
        guard let currentWeight =
                viewModel.currentWeight else {
            
            errorMessage =
                "Your current weight could not be found."
            
            return
        }
        
        
        let databaseGoalType: String
        let targetWeight: Double
        
        
        switch weightGoalType {
            
        case "Lose Weight":
            
            guard let amount =
                    Double(weightAmount),
                  amount > 0 else {
                
                errorMessage =
                    "Enter a valid amount of weight to lose."
                
                return
            }
            
            
            let newTarget =
                currentWeight - amount
            
            
            guard newTarget > 0 else {
                
                errorMessage =
                    "Target weight must be greater than 0."
                
                return
            }
            
            
            databaseGoalType = "lose_weight"
            targetWeight = newTarget
            
            
        case "Gain Weight":
            
            guard let amount =
                    Double(weightAmount),
                  amount > 0 else {
                
                errorMessage =
                    "Enter a valid amount of weight to gain."
                
                return
            }
            
            
            databaseGoalType = "gain_weight"
            
            targetWeight =
                currentWeight + amount
            
            
        case "Maintain Weight":
            
            databaseGoalType = "maintain_weight"
            targetWeight = currentWeight
            
            
        default:
            
            errorMessage = "Invalid weight goal."
            return
        }
        
        
        isSavingWeightGoal = true
        
        
        Task {
            
            let wasSaved =
                await viewModel.saveGoal(
                    goalType: databaseGoalType,
                    startingValue: currentWeight,
                    targetValue: targetWeight,
                    unit: "lbs",
                    targetDate: hasWeightTargetDate
                    ? weightTargetDate
                    : nil
                )
            
            
            isSavingWeightGoal = false
            
            
            if wasSaved {
                
                successMessage =
                    "Weight goal updated."
                
                weightAmount = ""
                
            } else {
                
                errorMessage =
                    viewModel.errorMessage
            }
        }
    }
    
    
    // MARK: - Save Step Goal
    
    private func saveStepGoal() {
        
        errorMessage = ""
        successMessage = ""
        
        
        guard let target =
                Int(stepTarget),
              target > 0 else {
            
            errorMessage =
                "Enter a valid daily step goal."
            
            return
        }
        
        
        isSavingStepGoal = true
        
        
        Task {

            let wasSaved =
                await viewModel.saveGoal(
                    goalType: "increase_steps",
                    startingValue: 0,
                    targetValue: Double(target),
                    unit: "steps",
                    targetDate: hasStepTargetDate
                        ? stepTargetDate
                        : nil
                )

            isSavingStepGoal = false
            
            
            if wasSaved {
                
                successMessage =
                    "Daily step goal updated."
                
                stepTarget = ""
                
            } else {
                
                errorMessage =
                    viewModel.errorMessage
            }
        }
    }
    // MARK: - Format Goal Date

        private func formatGoalDate(_ dateString: String) -> String {

            let inputFormatter = DateFormatter()
            inputFormatter.dateFormat = "yyyy-MM-dd"
            inputFormatter.locale = Locale(identifier: "en_US_POSIX")
            inputFormatter.timeZone = TimeZone(secondsFromGMT: 0)

            guard let date = inputFormatter.date(from: dateString) else {
                return dateString
            }

            let outputFormatter = DateFormatter()
            outputFormatter.dateStyle = .medium
            outputFormatter.timeZone = TimeZone(secondsFromGMT: 0)

            return outputFormatter.string(from: date)
        }
    
    
    // MARK: - Goal Time Remaining

    private func goalTimeRemaining(_ dateString: String) -> String {

        // Convert the saved date into a Date
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = .current

        guard let targetDate = formatter.date(from: dateString) else {
            return "Time remaining unavailable"
        }

        // Compare calendar days rather than hours
        let today = Calendar.current.startOfDay(for: Date())

        let daysRemaining = Calendar.current.dateComponents(
            [.day],
            from: today,
            to: targetDate
        ).day ?? 0

        if daysRemaining > 1 {
            return "\(daysRemaining) days remaining"

        } else if daysRemaining == 1 {
            return "1 day remaining"

        } else if daysRemaining == 0 {
            return "Today is your target/review date"

        } else {
            return "\(abs(daysRemaining)) days past target/review date"
        }
    }

}
